import math

# Add Day 10 interviews to Day 10 morning tracker:
with open("/tmp/opencode/tracker.py") as f:
    code = f.read()

# Let's append the 7 Day 10 interviews and compute exact EV of accusing now vs waiting 1 day!
d10_interviews = [
    ("e18", True),
    ("e18", False),
    ("e18", False),
    ("e18", True),
    ("e27", False),
    ("e27", False),
    ("e27", False),
]

import tracker
all_interviews = tracker.interviews + d10_interviews

for label, extra_frame in [("decoy_framing (lam_ah_inn=0.1263)", 0.0), ("random_colleague_framing (lam_ah_inn=0.1520)", 1/39)]:
    scores = {}
    for m in tracker.suspects:
        logp = math.log(0.95 if m in tracker.c1_A else 0.025)
        for emp, ev in all_interviews:
            if emp == m:
                logp += math.log(0.24 if ev else 0.76)
            else:
                logp += math.log(0.20 if ev else 0.80)
        for d in range(1, 10):
            for emp in tracker.suspects:
                day_reg = sum(1 for dd, ee, ah in tracker.logs if dd == d and ee == emp and not ah)
                day_ah = sum(1 for dd, ee, ah in tracker.logs if dd == d and ee == emp and ah)
                if emp == m:
                    lam_reg, lam_ah = 0.70, 0.30
                else:
                    lam_reg, lam_ah = 0.90, 0.10 + (1.0 / 38.0) + extra_frame
                logp += math.log(tracker.poisson_pmf(day_reg, lam_reg))
                logp += math.log(tracker.poisson_pmf(day_ah, lam_ah))
        scores[m] = logp
    max_lp = max(scores.values())
    probs = {m: math.exp(lp - max_lp) for m, lp in scores.items()}
    Z = sum(probs.values())
    probs = {m: p / Z for m, p in probs.items()}
    print(f"\n=== After Day 10 Interviews: {label} ===")
    for m, p in sorted(probs.items(), key=lambda x: -x[1])[:6]:
        print(f"  {m}: P = {p:.4f}")
    p_e18 = probs["e18"]
    # True V right now is ~0.64 (if 1 unsurfaced leak from D8/D9) or ~0.615
    for v_true in [0.69, 0.64, 0.59]:
        ev_now = p_e18 * v_true - (1 - p_e18) * 1.0
        print(f"  If true V={v_true:.2f}: EV(accuse e18 now) = {ev_now:.4f} (error risk cost = {(1-p_e18)*(1+v_true):.4f})")
